#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/stamp-standards-met.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * stamp-standards-met.mjs
 *
 * @version 1
 *
 * Creates the push stamp: an empty commit whose message literally says
 * "100% standards met". Refuses unless a FRESH green receipt exists —
 * the receipt is written only by verify-all.mjs on all-green, so the stamp
 * cannot exist without every gate having passed.
 *
 * Usage: node stamp-standards-met.mjs        (run from the web root, after pnpm verify)
 * Exit: 0 stamped, 1 refused.
 */
import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { spawnSync } from "node:child_process";

const RED = "\x1b[31m";
const GREEN = "\x1b[32m";
const RESET = "\x1b[0m";
const MAX_AGE_MS = 10 * 60 * 1000; // receipt older than 10 min = stale; re-run pnpm verify

const gitDir = spawnSync("git", ["rev-parse", "--git-dir"], { encoding: "utf8" }).stdout?.trim();
if (!gitDir) { process.stderr.write(`${RED}❌ stamp-standards-met:${RESET} not a git repo\n`); process.exit(1); }
const receiptPath = (path.isAbsolute(gitDir) ? path.join(gitDir, "verify-receipt.json") : path.join(process.cwd(), gitDir, "verify-receipt.json"));

let receipt = null;
try { receipt = JSON.parse(fs.readFileSync(receiptPath, "utf8")); } catch { /* missing/garbled */ }
const age = receipt ? Date.now() - Date.parse(receipt.ts) : Infinity;
if (!receipt || !(age >= 0 && age <= MAX_AGE_MS)) {
  process.stderr.write(`${RED}❌ stamp-standards-met:${RESET} no fresh green receipt (run \`pnpm verify\` first; receipt expires after 10 min)\n`);
  process.exit(1);
}

const dirty = spawnSync("git", ["status", "--porcelain"], { encoding: "utf8" }).stdout?.trim();
if (dirty) {
  process.stderr.write(`${RED}❌ stamp-standards-met:${RESET} working tree dirty — the receipt proves the VERIFIED state; commit your changes, re-run \`pnpm verify\`, then stamp\n`);
  process.exit(1);
}

// Subject stays ≤65 chars (pre-push rule); gate count + timestamp go in the body.
const subject = "chore: 100% standards met";
const bodyLine = `${receipt.gates}/${receipt.gates} gates green at ${receipt.ts}`;
const res = spawnSync("git", ["commit", "--allow-empty", "-m", subject, "-m", bodyLine], { encoding: "utf8", stdio: "inherit" });
if (res.status !== 0) process.exit(1);
process.stdout.write(`${GREEN}✅ stamp-standards-met${RESET} — ${subject} (${bodyLine})\n`);
